const r=[{id:"sales",roles:["sme_sales"],step:1},{id:"buy",roles:["sme_procurement"],step:1},{id:"hr",roles:["sme_hr"],step:1},{id:"fin",roles:["sme_accountant"],step:2},{id:"dir",roles:["sme_director"],step:3},{id:"bank",roles:["bank_reviewer"],step:4}],o=s=>r.find(e=>e.roles.includes(s));function l(s){return r.map(e=>({dept:e,people:s.filter(t=>e.roles.includes(t.role))})).filter(e=>e.people.length>0)}export{o as d,l as g};
